rules.summary:
[
  {
    "if": "Patient displays significant emotional pain or distress during session.",
    "then": "Make timely empathic comments and validate feelings, but balance concern with forward movement toward CBT intervention."
  },
  {
    "if": "Patient expresses maladaptive thoughts or cognitive distortions.",
    "then": "Use Socratic questioning and collaborative empiricism to challenge and reframe cognitions."
  },
  {
    "if": "Patient is new to CBT or struggles with engagement/completing homework.",
    "then": "Actively structure the session, model exercises, provide supportive feedback, and explain CBT concepts clearly."
  },
  {
    "if": "Patient or therapist notices a transference or countertransference reaction affecting alliance or session progress.",
    "then": "Discuss openly, analyze the relevant thoughts and beliefs, and apply CBT techniques to address and modify them."
  },
  {
    "if": "Patient’s sociocultural background or situational stress presents unique needs or expectations.",
    "then": "Flexibly adapt the therapeutic approach to be sensitive and responsive, seeking consultation or resources as needed."
  },
  {
    "if": "Patient makes requests regarding boundaries or session structure that are ethically appropriate.",
    "then": "Attempt to accommodate within professional guidelines; otherwise, explain and uphold boundaries respectfully."
  },
  {
    "if": "Therapist experiences negative emotional responses, frustration, or attraction during or after sessions.",
    "then": "Self-reflect to assess countertransference, identify underlying cognitions, and seek supervision or adapt approach as indicated."
  },
  {
    "if": "Therapist considers using humor in session.",
    "then": "Ensure humor is constructive, spontaneous, focused on external problems/incongruity, and never at the patient’s expense."
  }
]

- {"if": "Patient presents with severe cognitive impairment (advanced dementia or amnestic disorder)", "then": "Do not offer CBT; seek alternative interventions."}
- {"if": "Patient expresses marked pessimism or hopelessness with signs of suicidal ideation", "then": "Assess thoroughly for risk; consider alternate therapies or hospitalization."}
- {"if": "Patient demonstrates difficulty accessing automatic thoughts and associated emotions", "then": "Use targeted probes and exercises to elicit and practice identification of thoughts and emotions."}
- {"if": "Patient is not receptive to CBT rationale or refuses to attempt homework", "then": "Provide additional psychoeducation and preparation before proceeding."}
- {"if": "New information emerges during the course of therapy (e.g., change in symptoms, strengths, or new obstacles)", "then": "Revise case conceptualization and treatment plan accordingly."}
- {"if": "Patient has comorbid substance abuse, personality disorders, or trauma history", "then": "Anticipate need for a longer therapy course and consider modifications to intervention strategy."}
- {"if": "Session begins or ends", "then": "Administer standardized symptom scale (e.g., PHQ-9, GAD-7) and review progress."}
- {"if": "Patient provides feedback or reaction to session", "then": "Directly solicit feedback and integrate into assessment of alliance and plan modifications."}

- {"if": "A mood shift or intense emotional response emerges during session", "then": "Pause content exploration and direct empathic, supportive questions to uncover possible related schemas."}  
- {"if": "Recurring patterns in automatic thoughts are observed", "then": "Probe for underlying core beliefs using guided discovery or the downward arrow technique."}  
- {"if": "Patient appears confused or apprehensive about schema work", "then": "Clearly explain the rationale and collaborative nature of the intervention before proceeding."}  
- {"if": "Therapeutic rapport and prior successes in cognitive work are present", "then": "You may engage in deeper schema-discovery techniques, such as the downward arrow method."}  
- {"if": "Modifying a schema is attempted", "then": "Examine evidence for and against the schema, spot cognitive errors, and collaboratively generate alternative beliefs."}  
- {"if": "Modifying a schema produces both positive and negative effects for the patient", "then": "List advantages and disadvantages, and use this analysis to tailor schema modifications."}  
- {"if": "Patient endorses rigid, absolutist schemas", "then": "Use the cognitive continuum technique to help moderate and contextualize beliefs."}  
- {"if": "New or revised schema is developed in session", "then": "Plan rehearsal (role-play, imagery, homework) and review practice outcomes in future sessions."}  
- {"if": "Patient/personal schema list is developed", "then": "Regularly review and update it to reflect progress and new discoveries."}  
- {"if": "Patient expresses personal growth-oriented goals", "then": "Shift focus to building adaptive, meaningful core beliefs aligned with those aspirations."}

- {"if": "Patient expresses hopelessness about treatment or prior therapies", "then": "Listen empathically, validate hopelessness, and assess how prior negative experiences affect current attitudes; avoid early cognitive restructuring without foundation."}
- {"if": "Session begins with a patient at risk of suicide", "then": "Conduct comprehensive suicide risk assessment, including direct questioning about suicidality and reviewing self-report measures."}
- {"if": "Patient reports recent suicidal ideation or attempt", "then": "Conduct a narrative interview to elicit context, triggers, and timeline of the crisis."}
- {"if": "Developing safety plan with patient", "then": "Collaboratively identify warning signs, coping strategies, social supports, contacts for help, professional resources, and steps to limit access to lethal means; use patient's own words and troubleshoot barriers."}
- {"if": "Patient struggles to generate reasons for living", "then": "Suggest examples, inquire about past interests, and probe for protective factors obscured by depression."}
- {"if": "Implementing difficult or aversive therapeutic interventions", "then": "Prepare and inform the patient, obtain verbal consent, and respect preferences if patient declines."}
- {"if": "Therapist experiences distress, frustration, or hopelessness when treating suicidal patients", "then": "Reflect on automatic thoughts and emotions, employ CBT coping tools, seek supervisor/peer consultation, and avoid transmitting hopelessness to the patient."}
- {"if": "Ending/tapering treatment", "then": "Review skills learned, summarize key points, consolidate coping tools (therapy notebook, hope kit), and introduce relapse prevention tasks."}
- {"if": "Relapse prevention task is conducted", "then": "Guide the patient through past/future suicidal crises via imagery, practice coping strategies, debrief afterwards, and assess for emergent suicidal ideation."}
- {"if": "Patient lacks access to their safety plan during a crisis", "then": "Review and discuss with patient where the safety plan will be stored for easy access."}
- {"if": "There are environmental risks (e.g., access to firearms)", "then": "Collaboratively problem-solve and implement steps to make the environment safer."}
